    vector<int> eventualSafeNodes(int V, vector<int> adj[]) {
        vector<int> vis(V, 0);
        vector<int> pathVis(V, 0);

        for(int i = 0; i < V; i++){
            if(!vis[i]){
                dfs(i, adj, vis, pathVis);
            }
        }

        vector<int> ans;
        for(int i = 0; i < V; i++){
            if(pathVis[i] == 0){
                ans.push_back(i);
            }
        }

        return ans;
    }

private:
    bool dfs(int node, vector<int> adj[], vector<int>& vis, vector<int>& pathVis){
        vis[node] = 1;
        pathVis[node] = 1;

        //immediately return true if cycle found without unmarking the pathVis
        for(auto it : adj[node]){
            if(vis[it] == 0){
                if(dfs(it, adj, vis, pathVis)) return true;
            }
            else if(pathVis[it] == 1) return true;
        }

        pathVis[node] = 0;

        return false;
    }
};
